// Package servertext is the server's catalog (i18n/server, embedded) and a typed constructor per key, generated by
// pkg/i18n/cmd/i18ngen: card text, step labels, toasts and notices, rendered in the target screen's language.
package servertext

import (
	"embed"
	"sync"

	"git.shino.boo/devilreef/cadence/pkg/i18n"
)

// a copy of i18n/server, which make i18n writes
//
//go:embed server/*.json
var files embed.FS

// Catalog is the server's catalog, loaded once. Its files are checked by i18ngen before they are copied here, so a
// load failure is a broken build.
var Catalog = sync.OnceValue(func() *i18n.Catalog {
	c, err := i18n.Load(files, "server")
	if err != nil {
		panic(err)
	}
	return c
})

// Render renders a text in a language (a device's language setting, normalized).
func Render(lang string, t i18n.Text) string {
	return Catalog().RenderText(i18n.Normalize(lang), t)
}
